function:private.audit_change().definition:
CREATE OR REPLACE FUNCTION private.audit_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare changed text[];
begin
 if tg_op='UPDATE' then select coalesce(array_agg(n.key),'{}') into changed from jsonb_each(to_jsonb(new)) n where n.value is distinct from to_jsonb(old)->n.key;
 else select array_agg(key) into changed from jsonb_each(to_jsonb(new)); end if;
 insert into public.audit_events(organization_id,actor_id,table_name,record_id,operation,changed_fields)
 values(new.organization_id,auth.uid(),tg_table_name,coalesce(to_jsonb(new)->>'id',to_jsonb(new)->>'user_id',new.organization_id::text),tg_op,changed);
 return new;
end; $function$

function:private.route_safety().definition:
CREATE OR REPLACE FUNCTION private.route_safety()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_table_name='routes' then
  if tg_op='UPDATE' and (new.archived or new.pickup_location_id<>old.pickup_location_id or new.dropoff_location_id<>old.dropoff_location_id) and exists(select 1 from public.route_pricing where route_id=new.id and organization_id=new.organization_id and not archived) then raise exception 'Archive related prices before changing this route'; end if;
  perform 1 from public.locations where organization_id=new.organization_id and id in (new.pickup_location_id,new.dropoff_location_id) order by id for share;
  if not new.archived and (select count(*) from public.locations where organization_id=new.organization_id and id in (new.pickup_location_id,new.dropoff_location_id) and not archived)<>2 then raise exception 'Choose active pickup and drop-off locations'; end if;
 elsif tg_table_name='locations' then
  if new.archived and exists(select 1 from public.routes where organization_id=new.organization_id and not archived and (pickup_location_id=new.id or dropoff_location_id=new.id)) then raise exception 'Archive related routes before archiving this location'; end if;
 end if; return new;
end; $function$

function:private.check_archive().definition:
CREATE OR REPLACE FUNCTION private.check_archive()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.archived and (tg_op = 'INSERT' or not old.archived) then
    if tg_table_name = 'bookings' then
      if new.status not in ('completed','cancelled') then raise exception 'Complete or cancel a booking before archiving it'; end if;
    elsif tg_table_name in ('drivers','vehicles','customers','locations') then
      if exists (
        select 1 from public.bookings b where b.organization_id = new.organization_id and not b.archived and b.status not in ('completed','cancelled')
        and case tg_table_name when 'drivers' then b.driver_id = new.id when 'vehicles' then b.vehicle_id = new.id when 'customers' then b.customer_id = new.id else b.pickup_location_id = new.id or b.dropoff_location_id = new.id end
      ) then raise exception 'This record is assigned to an active booking'; end if;
      if tg_table_name = 'locations' and exists (select 1 from public.route_pricing p where p.organization_id = new.organization_id and not p.archived and (p.pickup_location_id = new.id or p.dropoff_location_id = new.id)) then raise exception 'Archive related route prices before archiving this location'; end if;
    end if;
  end if;
  if tg_table_name = 'route_pricing' and not new.archived then
    if (select count(*) from public.locations where organization_id = new.organization_id and id in (new.pickup_location_id,new.dropoff_location_id) and not archived) <> 2 then raise exception 'Choose active pickup and drop-off locations'; end if;
  end if;
  return new;
end; $function$

function:private.prepare_price().definition:
CREATE OR REPLACE FUNCTION private.prepare_price()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare route public.routes;
begin
 select * into route from public.routes where organization_id=new.organization_id and id=new.route_id and not archived for share;
 if not found then raise exception 'Choose an active route'; end if;
 new.pickup_location_id=route.pickup_location_id; new.dropoff_location_id=route.dropoff_location_id; new.name=route.name;
 return new;
end; $function$

function:private.prepare_record().definition:
CREATE OR REPLACE FUNCTION private.prepare_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' then
    if new.id <> old.id or new.organization_id <> old.organization_id or new.created_at <> old.created_at then raise exception 'Record identity cannot be changed'; end if;
    new.updated_at = now();
  end if;
  return new;
end; $function$

function:private.booking_history().definition:
CREATE OR REPLACE FUNCTION private.booking_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='INSERT' or new.status is distinct from old.status then
  insert into public.booking_status_history(organization_id,booking_id,old_status,new_status,reason,actor_id) values(new.organization_id,new.id,case when tg_op='UPDATE' then old.status else null end,new.status,new.cancellation_reason,auth.uid());
 end if;
 if tg_op='INSERT' or new.driver_id is distinct from old.driver_id or new.vehicle_id is distinct from old.vehicle_id then
  insert into public.booking_assignments(organization_id,booking_id,driver_id,vehicle_id,actor_id) values(new.organization_id,new.id,new.driver_id,new.vehicle_id,auth.uid());
 end if;
 return new;
end; $function$

function:private.validate_booking().definition:
CREATE OR REPLACE FUNCTION private.validate_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare fleet public.vehicles; buffer integer;
begin
 if tg_op='INSERT' and new.status<>'pending' then raise exception 'New bookings must start as pending'; end if;
 if tg_op='INSERT' and (new.end_at is null or new.vehicle_category is null or new.luggage is null) then raise exception 'Enter a journey end time and vehicle category'; end if;
 if tg_op='UPDATE' then
   if new.payment_status is distinct from old.payment_status then raise exception 'Payments require verified provider records'; end if;
   if new.status<>old.status and not (
     (old.status='pending' and new.status in ('confirmed','cancelled')) or
     (old.status='confirmed' and new.status in ('in_progress','cancelled')) or
     (old.status='in_progress' and new.status in ('completed','cancelled'))
   ) then raise exception 'This booking status transition is not allowed'; end if;
 end if;
 if new.status='cancelled' and (tg_op='INSERT' or new.status is distinct from old.status) and length(trim(coalesce(new.cancellation_reason,'')))=0 then raise exception 'Record a cancellation reason'; end if;
 if (tg_op='INSERT' and new.flight_status<>'not_recorded') or (tg_op='UPDATE' and new.flight_status is distinct from old.flight_status) then
   if new.flight_status<>'not_recorded' and length(trim(coalesce(new.flight_number,'')))=0 then raise exception 'Enter a flight number before recording its status'; end if;
   new.flight_status_updated_at=now();
 elsif tg_op='UPDATE' then new.flight_status_updated_at=old.flight_status_updated_at; end if;
 if tg_op='INSERT' and new.payment_status<>'unpaid' then raise exception 'Payments require verified provider records'; end if;
 select coalesce(turnaround_minutes,0) into buffer from public.business_settings where organization_id=new.organization_id;
 new.reserved_until=case when new.end_at is null then null else new.end_at+make_interval(mins=>coalesce(buffer,0)) end;
 if new.archived or new.status in ('completed','cancelled') then return new; end if;
 if new.status in ('confirmed','in_progress') and (new.driver_id is null or new.vehicle_id is null or new.end_at is null or new.vehicle_category is null) then raise exception 'Assign a driver, vehicle, category and end time before confirming'; end if;
 if new.status in ('confirmed','in_progress') and exists(select 1 from public.bookings b where b.organization_id=new.organization_id and b.id<>new.id and not b.archived and b.status in ('confirmed','in_progress') and b.reserved_until is null and b.pickup_at<new.reserved_until and (b.driver_id=new.driver_id or b.vehicle_id=new.vehicle_id)) then raise exception 'Record the end time of an existing assignment before confirming another trip'; end if;
 if not exists (select 1 from public.customers where organization_id=new.organization_id and id=new.customer_id and not archived) then raise exception 'Choose an active customer'; end if;
 if (select count(*) from public.locations where organization_id=new.organization_id and id in (new.pickup_location_id,new.dropoff_location_id) and not archived)<>2 then raise exception 'Choose active pickup and drop-off locations'; end if;
 if new.driver_id is not null and not exists (select 1 from public.drivers where organization_id=new.organization_id and id=new.driver_id and not archived and account_status='active' and status<>'unavailable' and (license_expiry is null or license_expiry>=(new.pickup_at at time zone 'Asia/Dubai')::date)) then raise exception 'Driver is unavailable or licence has expired'; end if;
 if new.vehicle_id is not null then
  select * into fleet from public.vehicles where organization_id=new.organization_id and id=new.vehicle_id and not archived and status not in ('maintenance','unavailable','inactive');
  if not found or fleet.luggage_capacity is null or new.luggage is null or fleet.capacity<new.passengers or fleet.luggage_capacity<new.luggage or (new.vehicle_category is not null and fleet.category<>new.vehicle_category) or (fleet.registration_expiry is not null and fleet.registration_expiry<(new.pickup_at at time zone 'Asia/Dubai')::date) then raise exception 'Vehicle is unavailable, incompatible or has insufficient capacity'; end if;
 end if;
 return new;
end; $function$

function:private.clear_trip_tracking().definition:
CREATE OR REPLACE FUNCTION private.clear_trip_tracking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.driver_id is distinct from old.driver_id or new.status='cancelled' then
  delete from public.driver_trip_progress where booking_id=new.id and completed_at is null;
 end if;
 if new.status='completed' then update public.driver_trip_progress set completed_at=now() where booking_id=new.id and completed_at is null; end if;
 if new.driver_id is distinct from old.driver_id or new.vehicle_id is distinct from old.vehicle_id or new.status is distinct from old.status or new.archived then
  if new.driver_id is distinct from old.driver_id or new.status not in ('confirmed','in_progress') or new.archived then delete from public.trip_live_locations where booking_id=new.id; delete from public.trip_location_consent where booking_id=new.id; end if;
  perform private.notify_tracking(new.id);
 end if; return new;
end; $function$

function:private.accept_staff_invitation.definition:
CREATE OR REPLACE FUNCTION private.accept_staff_invitation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare invitation public.staff_invitations;
begin
 select * into invitation from public.staff_invitations where email=lower(new.email) and accepted_at is null and expires_at>now() for update;
 if found then
  if invitation.role='driver' and not exists(select 1 from public.drivers where id=invitation.driver_id and organization_id=invitation.organization_id and account_status='active' and not archived and auth_user_id is null) then raise exception 'Driver is not available for invitation'; end if;
  insert into public.staff_members(user_id,organization_id,email,display_name,role) values(new.id,invitation.organization_id,invitation.email,invitation.display_name,invitation.role);
  if invitation.role='driver' then update public.drivers set auth_user_id=new.id where id=invitation.driver_id and organization_id=invitation.organization_id; end if;
  update public.staff_invitations set accepted_at=now() where id=invitation.id;
 end if; return new;
end; $function$

function:private.lock_referenced_records.definition:
CREATE OR REPLACE FUNCTION private.lock_referenced_records()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 -- Consistent order and row locks prevent archive/availability changes racing booking validation.
 perform 1 from public.locations where organization_id=new.organization_id and id in (new.pickup_location_id,new.dropoff_location_id) order by id for share;
 perform 1 from public.customers where organization_id=new.organization_id and id=new.customer_id for share;
 perform 1 from public.drivers where organization_id=new.organization_id and id=new.driver_id for share;
 perform 1 from public.vehicles where organization_id=new.organization_id and id=new.vehicle_id for share;
 return new;
end; $function$

function:public.begin_trip_location(trip.definition:
CREATE OR REPLACE FUNCTION public.begin_trip_location(trip_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare driver uuid;trip public.bookings;session uuid;begin
 driver=private.assigned_driver_id();
 select * into trip from public.bookings where id=trip_id and driver_id=driver for update;
 if not found or not private.live_trip_matches(trip_id,driver,trip.organization_id) then raise exception 'Active assignment required' using errcode='42501'; end if;
 if exists(select 1 from public.trip_location_consent where booking_id=trip_id and started_at>clock_timestamp()-interval '5 seconds') then raise exception 'Wait before restarting sharing'; end if;
 insert into public.trip_location_consent(booking_id,driver_id,session_id,started_at,expires_at) values(trip_id,driver,gen_random_uuid(),clock_timestamp(),clock_timestamp()+interval '2 minutes')
 on conflict(booking_id) do update set driver_id=excluded.driver_id,session_id=excluded.session_id,started_at=excluded.started_at,expires_at=excluded.expires_at
 returning session_id into session;
 delete from public.trip_live_locations where booking_id=trip_id; perform private.notify_tracking(trip_id); return session;
end; $function$

function:private.tracking_topic_allowed(.definition:
CREATE OR REPLACE FUNCTION private.tracking_topic_allowed(topic text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare identifier uuid; begin
 if topic~'^trip:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return private.can_track(substring(topic from 6)::uuid); end if;
 if topic~'^operations-tracking:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
  identifier=substring(topic from 21)::uuid;
  return exists(select 1 from public.staff_members m where m.user_id=auth.uid() and m.active and m.organization_id=identifier and m.role in ('owner','manager','dispatcher','viewer'));
 end if; return false;
end; $function$

function:public.driver_trip_history(page.definition:
CREATE OR REPLACE FUNCTION public.driver_trip_history(page_number integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare driver uuid; begin
 driver=private.assigned_driver_id(); if driver is null then raise exception 'Driver access required' using errcode='42501'; end if;
 if page_number<1 or page_number>10000 then raise exception 'Invalid page'; end if;
 return coalesce((select jsonb_agg(t) from (
  select b.reference,a.name as pickup,z.name as destination,b.pickup_at,h.completed_at
  from public.bookings b join public.locations a on a.id=b.pickup_location_id join public.locations z on z.id=b.dropoff_location_id
  left join lateral(select min(created_at) as completed_at from public.booking_status_history where booking_id=b.id and new_status='completed') h on true
  where b.driver_id=driver and b.status='completed' order by h.completed_at desc nulls last,b.pickup_at desc limit 20 offset ((page_number-1)*20)
 ) t),'[]'::jsonb);
end; $function$

function:public.payment_reserve(trip uui.definition:
CREATE OR REPLACE FUNCTION public.payment_reserve(trip uuid, passenger uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.bookings; attempt public.payment_attempts;begin
 select * into b from public.bookings where id=trip for update;
 if not found or b.status<>'confirmed' or b.archived or b.price_aed<=0 or b.price_aed>10000000 or not exists(select 1 from public.passenger_booking_accounts a join public.passenger_profiles p on p.user_id=a.user_id and p.organization_id=a.organization_id and p.active join auth.users u on u.id=a.user_id where a.booking_id=trip and a.user_id=passenger and u.email_confirmed_at is not null and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now()) and not exists(select 1 from public.staff_members m where m.user_id=passenger)) then raise exception 'Payment unavailable' using errcode='42501';end if;
 if exists(select 1 from public.verified_payments where booking_id=trip) then raise exception 'Payment already recorded. Contact our team';end if;
 insert into public.payment_attempts(booking_id,organization_id,user_id,amount_minor) values(trip,b.organization_id,passenger,(b.price_aed*100)::bigint) on conflict(booking_id) do nothing;
 select * into attempt from public.payment_attempts where booking_id=trip;
 if attempt.status not in ('creating','open') then raise exception 'Payment requires reconciliation';end if;
 return to_jsonb(attempt)||jsonb_build_object('reference',b.reference);end;$function$

function:public.cancel_staff_invitation(.definition:
CREATE OR REPLACE FUNCTION public.cancel_staff_invitation(invitation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare org uuid;
begin
 org=private.organization_id(); perform 1 from public.organizations where id=org for update;
 if private.current_role() is distinct from 'owner' then raise exception 'Only the owner may cancel invitations'; end if;
 update public.drivers d set account_status='inactive' from public.staff_invitations i where i.id=invitation_id and i.organization_id=org and d.organization_id=org and d.id=i.driver_id;
 update public.staff_members m set active=false from public.staff_invitations i where i.id=invitation_id and i.organization_id=org and m.organization_id=org and lower(m.email)=i.email and m.role<>'owner';
 update public.staff_invitations set expires_at=now() where id=invitation_id and organization_id=org;
end; $function$

function:public.reserve_driver_invitatio.definition:
CREATE OR REPLACE FUNCTION public.reserve_driver_invitation(target_driver_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare org uuid; d public.drivers; invite_id uuid;
begin
 org=private.organization_id(); perform 1 from public.organizations where id=org for update;
 if private.current_role() is distinct from 'owner' then raise exception 'Only the owner may invite drivers'; end if;
 select * into d from public.drivers where organization_id=org and id=target_driver_id and not archived and account_status='active' for update;
 if not found or d.auth_user_id is not null or d.email is null then raise exception 'Choose an active driver with an email and no existing account'; end if;
 if exists(select 1 from auth.users where lower(email)=lower(trim(d.email))) then raise exception 'This email already has an account'; end if;
 delete from public.staff_invitations where organization_id=org and email=lower(trim(d.email)) and accepted_at is null and expires_at<now();
 insert into public.staff_invitations(organization_id,email,display_name,role,driver_id,invited_by) values(org,lower(trim(d.email)),d.name,'driver',d.id,auth.uid()) returning id into invite_id;
 return invite_id;
end; $function$

function:public.concierge_consume(subjec.definition:
CREATE OR REPLACE FUNCTION public.concierge_consume(subject text, business_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare bucket timestamptz:=date_trunc('hour',now()); used_count integer;begin
 if subject !~ '^[a-f0-9]{64}$' then raise exception 'Invalid subject';end if;
 -- Lock both limits before consuming; only trusted server may invoke.
 perform pg_advisory_xact_lock(hashtextextended(business_id::text||bucket::text,0));
 select used into used_count from public.concierge_usage where subject_hash=encode(extensions.digest(business_id::text,'sha256'),'hex') and window_start=bucket;
 if coalesce(used_count,0)>=200 then return false;end if;
 select used into used_count from public.concierge_usage where subject_hash=subject and window_start=bucket;
 if coalesce(used_count,0)>=10 then return false;end if;
 insert into public.concierge_usage values(subject,bucket,1) on conflict(subject_hash,window_start) do update set used=public.concierge_usage.used+1;
 insert into public.concierge_usage values(encode(extensions.digest(business_id::text,'sha256'),'hex'),bucket,1) on conflict(subject_hash,window_start) do update set used=public.concierge_usage.used+1;
 delete from public.concierge_usage where window_start<now()-interval '48 hours';return true;end;$function$

function:public.stop_trip_location(trip_.definition:
CREATE OR REPLACE FUNCTION public.stop_trip_location(trip_id uuid, consent_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform 1 from public.bookings where id=trip_id and driver_id=private.assigned_driver_id() for update;
 if not found then raise exception 'Assignment required' using errcode='42501'; end if;
 if not exists(select 1 from public.trip_location_consent where booking_id=trip_id and session_id=consent_id) then return; end if;
 delete from public.trip_location_consent where booking_id=trip_id;
 delete from public.trip_live_locations where booking_id=trip_id; perform private.notify_tracking(trip_id);
end; $function$

function:public.driver_trip_action(trip_.definition:
CREATE OR REPLACE FUNCTION public.driver_trip_action(trip_id uuid, action_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare driver uuid; trip public.bookings; progress public.driver_trip_progress;
begin
 driver=private.assigned_driver_id();
 if driver is null then raise exception 'Driver access required' using errcode='42501'; end if;
 select * into trip from public.bookings where id=trip_id and driver_id=driver and not archived for update;
 if not found or trip.status not in ('confirmed','in_progress') then raise exception 'Assigned active trip required' using errcode='42501'; end if;
 insert into public.driver_trip_progress(booking_id,driver_id) values(trip_id,driver) on conflict do nothing;
 select * into progress from public.driver_trip_progress where booking_id=trip_id for update;
 if progress.driver_id<>driver then raise exception 'Dispatcher must review reassigned trip progress'; end if;
 if action_name<>'complete' and exists(select 1 from public.drivers where id=driver and license_expiry<(now() at time zone 'Asia/Dubai')::date) then raise exception 'Driver licence requires dispatcher review'; end if;
 if action_name in ('en_route','pickup','handover') then update public.bookings set updated_at=now() where id=trip_id; end if;
 case action_name
 when 'accept' then
  if trip.status<>'confirmed' or progress.accepted_at is not null then raise exception 'Trip cannot be accepted'; end if;
  update public.driver_trip_progress set accepted_at=now() where booking_id=trip_id;
 when 'en_route' then
  if trip.status<>'confirmed' or progress.accepted_at is null or progress.en_route_at is not null then raise exception 'Accept the trip before departure'; end if;
  update public.driver_trip_progress set en_route_at=now() where booking_id=trip_id;
 when 'handover' then
  if trip.status<>'in_progress' or progress.accepted_at is not null then raise exception 'An authorized active reassignment is required'; end if;
  update public.driver_trip_progress set accepted_at=now(),handover_at=now() where booking_id=trip_id;
 when 'arrive' then
  if trip.status<>'confirmed' or progress.en_route_at is null or progress.arrived_at is not null then raise exception 'Record departure before marking arrival'; end if;
  update public.driver_trip_progress set arrived_at=now() where booking_id=trip_id;
 when 'pickup' then
  if trip.status<>'confirmed' or progress.arrived_at is null or progress.picked_up_at is not null then raise exception 'Record arrival before pickup'; end if;
  update public.bookings set status='in_progress' where id=trip_id;
  update public.driver_trip_progress set picked_up_at=now() where booking_id=trip_id;
 when 'complete' then
  if trip.status<>'in_progress' or (progress.picked_up_at is null and progress.handover_at is null) then raise exception 'Trip must be in progress'; end if;
  update public.bookings set status='completed' where id=trip_id;
  update public.driver_trip_progress set completed_at=now() where booking_id=trip_id;
 else raise exception 'Invalid trip action';
 end case;
 insert into public.driver_trip_events(booking_id,driver_id,actor_id,event) values(trip_id,driver,auth.uid(),action_name);
 perform private.notify_tracking(trip_id);
end; $function$

function:public.payment_failed(event_key.definition:
CREATE OR REPLACE FUNCTION public.payment_failed(event_key text, attempt uuid, session text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare p public.payment_attempts;begin
 select * into p from public.payment_attempts where id=attempt for update;
 if not found or session is distinct from p.session_id then raise exception 'Provider evidence mismatch';end if;
 insert into public.payment_webhook_events values(event_key,'failed',attempt,now()) on conflict(event_id) do nothing;
 if not found then return;end if;
 if p.status not in ('paid','refunded') then update public.payment_attempts set status='failed' where id=attempt;perform private.passenger_notice(p.booking_id,'payment_failed','failed:'||attempt);end if;end;$function$

function:public.passenger_quote(business.definition:
CREATE OR REPLACE FUNCTION public.passenger_quote(business_id uuid, vehicle uuid, journey_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=private.passenger_user(); v public.vehicles; config public.passenger_route_configuration; q jsonb; rules jsonb; quote uuid; duration_end timestamptz; pickup timestamptz; return_pickup timestamptz; extra uuid[];begin
 if journey_input is null or jsonb_typeof(journey_input)<>'object' or journey_input->>'pickup_id' is null or journey_input->>'dropoff_id' is null or journey_input->>'passengers' is null or journey_input->>'luggage' is null or journey_input->>'transfer_type' is null or journey_input->>'transfer_type' not in ('one_way','return') or length(coalesce(journey_input->>'flight',''))>200 or jsonb_typeof(coalesce(journey_input->'extras','[]'))<>'array' then raise exception 'Invalid journey';end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text||business_id::text,0));
 if not exists(select 1 from public.passenger_profiles p join public.customers c on c.id=p.customer_id where p.user_id=uid and p.organization_id=business_id and p.active and not c.archived) then raise exception 'Complete your passenger profile first';end if;
 if (select count(*) from public.passenger_quotes where organization_id=business_id and created_at>now()-interval '1 hour')>=1000 then raise exception 'Online quotes temporarily unavailable';end if;
 if (select count(*) from public.passenger_quotes where user_id=uid and created_at>now()-interval '1 hour')>=30 then raise exception 'Quote limit reached. Contact our team';end if;
 select jsonb_build_object('terms',s.terms,'privacy',s.privacy_policy,'booking_policy',b.booking_policy,'cancellation_policy',b.cancellation_policy) into rules from public.passenger_platform_settings s join public.business_settings b on b.organization_id=s.organization_id
 where s.organization_id=business_id and s.bookings_enabled and b.published and b.enquiries_enabled and length(trim(s.terms))>0 and length(trim(s.privacy_policy))>0 and length(trim(b.booking_policy))>0 and length(trim(b.cancellation_policy))>0;
 if rules is null then raise exception 'Online bookings unavailable. Request an enquiry';end if;
 select * into v from public.vehicles where id=vehicle and organization_id=business_id and public_listed and not archived and status in ('available','on_trip') for share;
 if not found or v.capacity<(journey_input->>'passengers')::integer or v.luggage_capacity is null or v.luggage_capacity<(journey_input->>'luggage')::integer or (journey_input->>'passengers')::integer not between 1 and 1000 or (journey_input->>'luggage')::integer not between 0 and 1000 then raise exception 'Vehicle capacity unavailable';end if;
 select c.* into config from public.passenger_route_configuration c join public.routes r on r.id=c.route_id and r.organization_id=c.organization_id where c.organization_id=business_id and c.enabled and not r.archived and r.pickup_location_id=(journey_input->>'pickup_id')::uuid and r.dropoff_location_id=(journey_input->>'dropoff_id')::uuid for share of c,r;
 if not found then raise exception 'This route requires a manual enquiry';end if;
 pickup=(journey_input->>'pickup_at')::timestamptz; return_pickup=nullif(journey_input->>'return_at','')::timestamptz;
 if pickup is null or pickup<now()+(select make_interval(hours=>minimum_notice_hours) from public.business_settings where organization_id=business_id) or (v.registration_expiry is not null and v.registration_expiry<(pickup at time zone 'Asia/Dubai')::date) then raise exception 'Check your pickup time';end if;
 duration_end=pickup+make_interval(mins=>config.journey_minutes);
 if return_pickup is not null and v.registration_expiry is not null and v.registration_expiry<(return_pickup at time zone 'Asia/Dubai')::date then raise exception 'Selected vehicle unavailable';end if;
 if journey_input->>'transfer_type'='return' and (config.return_minutes is null or return_pickup is null or return_pickup<=duration_end) then raise exception 'Return journey unavailable or overlaps outbound';end if;
 if journey_input->>'transfer_type'='one_way' and return_pickup is not null then raise exception 'Check your return journey';end if;
 select coalesce(array_agg(value::uuid),'{}') into extra from jsonb_array_elements_text(coalesce(journey_input->'extras','[]'));
 perform 1 from public.route_pricing where organization_id=business_id and pickup_location_id=(journey_input->>'pickup_id')::uuid and dropoff_location_id=(journey_input->>'dropoff_id')::uuid and vehicle_category=v.category for share;
 perform 1 from public.pricing_extras where organization_id=business_id and id=any(extra) order by id for share;
 q=public.calculate_transfer_quote(business_id,(journey_input->>'pickup_id')::uuid,(journey_input->>'dropoff_id')::uuid,v.category,journey_input->>'transfer_type',extra);
 insert into public.passenger_quotes(user_id,organization_id,vehicle_id,journey,pricing,terms_snapshot) values(uid,business_id,vehicle,journey_input||jsonb_build_object('category',v.category,'end_at',duration_end,'return_end_at',case when return_pickup is not null then return_pickup+make_interval(mins=>config.return_minutes) else null end),q,rules) returning id into quote;
 return jsonb_build_object('id',quote,'expires_at',now()+interval '10 minutes','pricing',q,'terms',rules,'availability','pending_dispatch');end;$function$

function:public.set_staff_access(target_.definition:
CREATE OR REPLACE FUNCTION public.set_staff_access(target_user_id uuid, new_role text, new_active boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare org uuid; previous_role text;
begin
 org=private.organization_id(); perform 1 from public.organizations where id=org for update;
 if private.current_role() is distinct from 'owner' then raise exception 'Only the owner may manage staff'; end if;
 if new_role is null or new_role not in ('owner','manager','dispatcher','viewer','driver') or new_active is null then raise exception 'Invalid access settings'; end if;
 select role into previous_role from public.staff_members where user_id=target_user_id and organization_id=org;
 if not found then raise exception 'Staff member not found'; end if;
 if (previous_role='driver') <> (new_role='driver') then raise exception 'Driver accounts cannot be changed to portal roles'; end if;
 if exists(select 1 from public.staff_members where user_id=target_user_id and role='owner' and active) and (new_role<>'owner' or not new_active) and (select count(*) from public.staff_members where organization_id=org and role='owner' and active)<=1 then raise exception 'Keep at least one active owner'; end if;
 update public.staff_members set role=new_role,active=new_active where user_id=target_user_id and organization_id=org;
 if previous_role='driver' then update public.drivers set account_status=case when new_active then 'active' else 'inactive' end where organization_id=org and auth_user_id=target_user_id; end if;
end; $function$

function:public.passenger_save_profile(b.definition:
CREATE OR REPLACE FUNCTION public.passenger_save_profile(business_id uuid, full_name text, phone_number text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=private.passenger_user(); customer uuid; mail text;begin
 if full_name is null or length(trim(full_name)) not between 1 and 200 or phone_number is null or length(trim(phone_number)) not between 7 and 100 then raise exception 'Check your name and phone number';end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text||business_id::text,0));
 if not exists(select 1 from public.business_settings where organization_id=business_id and published) then raise exception 'Business account unavailable';end if;
 select email into mail from auth.users where id=uid;
 select customer_id into customer from public.passenger_profiles where user_id=uid and organization_id=business_id and active;
 if customer is null then
 if exists(select 1 from public.passenger_profiles where user_id=uid and organization_id=business_id) then raise exception 'Account unavailable' using errcode='42501';end if;
 insert into public.customers(organization_id,name,email,phone) values(business_id,trim(full_name),mail,trim(phone_number)) returning id into customer;
 insert into public.passenger_profiles(user_id,organization_id,customer_id) values(uid,business_id,customer);
 else update public.customers set name=trim(full_name),email=mail,phone=trim(phone_number) where id=customer and not archived; if not found then raise exception 'Account unavailable';end if;end if;
 return jsonb_build_object('name',trim(full_name),'email',mail,'phone',trim(phone_number));end;$function$

function:public.reserve_staff_invitation.definition:
CREATE OR REPLACE FUNCTION public.reserve_staff_invitation(invite_email text, invite_name text, invite_role text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare org uuid; invite_id uuid; normalized_email text;
begin
  org := private.organization_id();
  perform 1 from public.organizations where id = org for update;
  if private.current_role() is distinct from 'owner' then raise exception 'Only the owner may invite staff'; end if;
  normalized_email := lower(trim(invite_email));
  if invite_role is null or invite_role not in ('manager','dispatcher','viewer') or invite_name is null or length(trim(invite_name)) not between 1 and 200 or normalized_email is null or length(normalized_email) > 254 or normalized_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then raise exception 'Invalid invitation'; end if;
  if exists (select 1 from auth.users where lower(email) = normalized_email) then raise exception 'This email already has an account. Manage existing staff access or contact the account owner'; end if;
  -- Expired reservations are removed only within the current organization.
  delete from public.staff_invitations where organization_id = org and email = normalized_email and accepted_at is null and expires_at < now();
  insert into public.staff_invitations(organization_id,email,display_name,role,invited_by) values (org,normalized_email,trim(invite_name),invite_role,auth.uid()) returning id into invite_id;
  return invite_id;
end; $function$

function:public.passenger_create_booking.definition:
CREATE OR REPLACE FUNCTION public.passenger_create_booking(quote_id uuid, request_id uuid, customer_notes text, acknowledged boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=private.passenger_user(); q public.passenger_quotes; fresh jsonb; v public.vehicles; customer uuid; trip uuid; result jsonb; extra uuid[];begin
 if request_id is null or acknowledged is distinct from true or length(coalesce(customer_notes,''))>4000 then raise exception 'Accept policies and check your instructions';end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text||request_id::text,0));
 select jsonb_agg(jsonb_build_object('id',b.id,'reference',b.reference,'status',b.status) order by b.pickup_at,b.id) into result from public.passenger_booking_accounts a join public.bookings b on b.id=a.booking_id where a.user_id=uid and a.request_key=request_id;
 if result is not null then if exists(select 1 from public.passenger_booking_accounts where user_id=uid and request_key=request_id and passenger_booking_accounts.quote_id<>passenger_create_booking.quote_id) then raise exception 'Request key already used';end if;return result;end if;
 select * into q from public.passenger_quotes where id=quote_id and user_id=uid for update;
 if not found or q.expires_at<=now() or q.consumed_key is not null then raise exception 'Quote expired. Request a fresh quote';end if;
 perform 1 from public.passenger_platform_settings s join public.business_settings b on b.organization_id=s.organization_id where s.organization_id=q.organization_id and s.bookings_enabled and b.published and b.enquiries_enabled and q.terms_snapshot=jsonb_build_object('terms',s.terms,'privacy',s.privacy_policy,'booking_policy',b.booking_policy,'cancellation_policy',b.cancellation_policy) for share of s,b;
 if not found then raise exception 'Policies changed. Request a fresh quote';end if;
 select customer_id into customer from public.passenger_profiles where user_id=uid and organization_id=q.organization_id and active for share;
 if customer is null then raise exception 'Account unavailable';end if;
 select * into v from public.vehicles where id=q.vehicle_id and organization_id=q.organization_id and public_listed and not archived and status in ('available','on_trip') for share;
 if not found or v.capacity<(q.journey->>'passengers')::integer or v.luggage_capacity is null or v.luggage_capacity<(q.journey->>'luggage')::integer or (v.registration_expiry is not null and v.registration_expiry<((q.journey->>'pickup_at')::timestamptz at time zone 'Asia/Dubai')::date) then raise exception 'Selected vehicle unavailable';end if;
 perform 1 from public.passenger_route_configuration c join public.routes r on r.id=c.route_id and r.organization_id=c.organization_id where c.organization_id=q.organization_id and c.enabled and not r.archived and r.pickup_location_id=(q.journey->>'pickup_id')::uuid and r.dropoff_location_id=(q.journey->>'dropoff_id')::uuid and (q.journey->>'end_at')::timestamptz=(q.journey->>'pickup_at')::timestamptz+make_interval(mins=>c.journey_minutes) and ((q.journey->>'return_at') is null or (q.journey->>'return_end_at')::timestamptz=(q.journey->>'return_at')::timestamptz+make_interval(mins=>c.return_minutes)) for share of c,r;
 if not found or (q.journey->>'pickup_at')::timestamptz<now()+(select make_interval(hours=>minimum_notice_hours) from public.business_settings where organization_id=q.organization_id) then raise exception 'Journey changed. Request a fresh quote';end if;
 select coalesce(array_agg(value::uuid),'{}') into extra from jsonb_array_elements_text(q.journey->'extras');
 perform 1 from public.route_pricing where id=(q.pricing->>'pricing_id')::uuid for share;
 perform 1 from public.pricing_extras where organization_id=q.organization_id and id=any(extra) order by id for share;
 fresh=public.calculate_transfer_quote(q.organization_id,(q.journey->>'pickup_id')::uuid,(q.journey->>'dropoff_id')::uuid,v.category,q.journey->>'transfer_type',extra);
 if fresh<>q.pricing then raise exception 'Pricing changed. Request a fresh quote';end if;
 insert into public.bookings(organization_id,customer_id,pickup_location_id,dropoff_location_id,pickup_at,end_at,passengers,luggage,vehicle_category,flight_number,status,price_aed,payment_status,notes)
 values(q.organization_id,customer,(q.journey->>'pickup_id')::uuid,(q.journey->>'dropoff_id')::uuid,(q.journey->>'pickup_at')::timestamptz,(q.journey->>'end_at')::timestamptz,(q.journey->>'passengers')::integer,(q.journey->>'luggage')::integer,v.category,nullif(q.journey->>'flight',''),'pending',(q.pricing->>'outbound_aed')::numeric,'unpaid',nullif(trim(customer_notes),'')) returning id into trip;
 insert into public.passenger_booking_accounts values(trip,uid,q.organization_id,request_id,q.id,now());
 if q.journey->>'transfer_type'='return' then
 insert into public.bookings(organization_id,customer_id,pickup_location_id,dropoff_location_id,pickup_at,end_at,passengers,luggage,vehicle_category,status,price_aed,payment_status,notes,return_of_booking_id)
 values(q.organization_id,customer,(q.journey->>'dropoff_id')::uuid,(q.journey->>'pickup_id')::uuid,(q.journey->>'return_at')::timestamptz,(q.journey->>'return_end_at')::timestamptz,(q.journey->>'passengers')::integer,(q.journey->>'luggage')::integer,v.category,'pending',(q.pricing->>'return_aed')::numeric,'unpaid',nullif(trim(customer_notes),''),trip) returning id into trip;
 insert into public.passenger_booking_accounts values(trip,uid,q.organization_id,request_id,q.id,now());end if;
 update public.passenger_quotes set consumed_key=request_id where id=q.id;
 select jsonb_agg(jsonb_build_object('id',b.id,'reference',b.reference,'status',b.status) order by b.pickup_at,b.id) into result from public.passenger_booking_accounts a join public.bookings b on b.id=a.booking_id where a.user_id=uid and a.request_key=request_id;
 return result;end;$function$

function:public.set_passenger_tracking(t.definition:
CREATE OR REPLACE FUNCTION public.set_passenger_tracking(trip_id uuid, passenger_id uuid, expiry timestamp with time zone, enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if private.current_role() is distinct from 'owner' or not private.can_track(trip_id) or not exists(select 1 from public.bookings where id=trip_id and organization_id=private.organization_id()) then raise exception 'Owner authorization required' using errcode='42501'; end if;
 if enabled is null then raise exception 'Choose an access action'; end if;
 if not enabled then
  update public.passenger_tracking_access set revoked=true where booking_id=trip_id and user_id=passenger_id;
  perform private.notify_tracking(trip_id);return;
 end if;
 if exists(select 1 from public.staff_members where user_id=passenger_id and role='driver') then raise exception 'Driver accounts cannot receive passenger tracking grants'; end if;
 if expiry is null or expiry<=now() or expiry>now()+interval '7 days' or not exists(select 1 from auth.users where id=passenger_id and email_confirmed_at is not null and deleted_at is null and (banned_until is null or banned_until<=now())) then raise exception 'Confirmed passenger and bounded expiry required'; end if;
 insert into public.passenger_tracking_access(booking_id,user_id,granted_by,expires_at,revoked) values(trip_id,passenger_id,auth.uid(),expiry,not enabled)
 on conflict(booking_id,user_id) do update set granted_by=excluded.granted_by,expires_at=excluded.expires_at,revoked=excluded.revoked;
 perform private.notify_tracking(trip_id);
end; $function$

function:public.convert_booking_enquiry(.definition:
CREATE OR REPLACE FUNCTION public.convert_booking_enquiry(target_enquiry_id uuid, outbound_end timestamp with time zone, return_end timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare org uuid; enquiry public.booking_enquiries; customer uuid; booking uuid;
begin
 org=private.organization_id();
 if private.current_role() is null or private.current_role() not in ('owner','manager','dispatcher') then raise exception 'Not permitted'; end if;
 select * into enquiry from public.booking_enquiries where id=target_enquiry_id and organization_id=org for update;
 if not found or enquiry.status not in ('new','reviewed') then raise exception 'This enquiry cannot be converted'; end if;
 if outbound_end is null or outbound_end<=enquiry.pickup_at or (enquiry.transfer_type='return' and (return_end is null or return_end<=enquiry.return_at or enquiry.return_at<=outbound_end)) or (enquiry.transfer_type='one_way' and return_end is not null) then raise exception 'Enter valid journey end times'; end if;
 -- Contact details originate from this genuine enquiry. Do not silently merge people with similar names.
 insert into public.customers(organization_id,name,email,phone) values(org,enquiry.name,enquiry.email,enquiry.phone) returning id into customer;
 insert into public.bookings(organization_id,customer_id,pickup_location_id,dropoff_location_id,pickup_at,end_at,passengers,luggage,vehicle_category,flight_number,status,price_aed,payment_status,notes,enquiry_id)
 values(org,customer,enquiry.pickup_location_id,enquiry.dropoff_location_id,enquiry.pickup_at,outbound_end,enquiry.passengers,enquiry.luggage,enquiry.vehicle_category,enquiry.flight_number,'pending',enquiry.quoted_outbound_aed,'unpaid',enquiry.notes,enquiry.id) returning id into booking;
 if enquiry.transfer_type='return' then
  insert into public.bookings(organization_id,customer_id,pickup_location_id,dropoff_location_id,pickup_at,end_at,passengers,luggage,vehicle_category,status,price_aed,payment_status,notes,enquiry_id,return_of_booking_id)
  values(org,customer,enquiry.dropoff_location_id,enquiry.pickup_location_id,enquiry.return_at,return_end,enquiry.passengers,enquiry.luggage,enquiry.vehicle_category,'pending',enquiry.quoted_return_aed,'unpaid',enquiry.notes,enquiry.id,booking);
 end if;
 update public.booking_enquiries set status='converted',updated_at=now() where id=enquiry.id;
 return booking;
end; $function$

function:public.calculate_transfer_quote.definition:
CREATE OR REPLACE FUNCTION public.calculate_transfer_quote(business_id uuid, pickup_id uuid, dropoff_id uuid, category text, transfer_kind text, extra_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.route_pricing; extra_out numeric:=0; extra_back numeric:=0; count_extras integer; outbound numeric; inbound numeric;
begin
 if not exists(select 1 from public.business_settings where organization_id=business_id and published and enquiries_enabled) then raise exception 'Online enquiries are unavailable'; end if;
 if transfer_kind is null or transfer_kind not in ('one_way','return') or category is null or category not in ('sedan','suv','van','luxury') or pickup_id=dropoff_id or extra_ids is null or cardinality(extra_ids)>20 then raise exception 'Check your journey details'; end if;
 if (select count(*) from public.locations where organization_id=business_id and id in (pickup_id,dropoff_id) and public_listed and not archived)<>2 then raise exception 'Choose published locations'; end if;
 select rp.* into p from public.route_pricing rp join public.routes r on r.id=rp.route_id and r.organization_id=rp.organization_id
 where rp.organization_id=business_id and rp.pickup_location_id=pickup_id and rp.dropoff_location_id=dropoff_id and rp.vehicle_category=category and rp.public_listed and not rp.archived and not r.archived;
 if not found then raise exception 'A quote is not available for this route and category'; end if;
 if transfer_kind='return' and p.return_fare_aed is null then raise exception 'Return pricing is not available for this route'; end if;
 select count(*),coalesce(sum(price_aed),0),coalesce(sum(price_aed) filter(where charge_basis='per_leg'),0) into count_extras,extra_out,extra_back
 from public.pricing_extras where organization_id=business_id and route_pricing_id=p.id and not archived and id=any(extra_ids);
 if count_extras<>cardinality(extra_ids) then raise exception 'Choose valid optional extras'; end if;
 outbound=p.price_aed+p.additional_charges_aed+extra_out;
 inbound=case when transfer_kind='return' then p.return_fare_aed+p.additional_charges_aed+extra_back else null end;
 return jsonb_build_object('pricing_id',p.id,'currency','AED','base_fare',p.price_aed,'additional_charges',p.additional_charges_aed,'outbound_aed',outbound,'return_aed',inbound,'total_aed',outbound+coalesce(inbound,0),'extras',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name,'price_aed',price_aed,'charge_basis',charge_basis) order by name) from public.pricing_extras where organization_id=business_id and route_pricing_id=p.id and not archived),'[]'::jsonb));
end; $function$

function:public.payment_record(event_key.definition:
CREATE OR REPLACE FUNCTION public.payment_record(event_key text, event_kind text, attempt uuid, session text, intent text, charge text, total_minor bigint, currency_code text, refund_total bigint DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.payment_attempts; delta bigint;begin
 select * into p from public.payment_attempts where id=attempt for update;
 if not found or currency_code is distinct from 'aed' or total_minor is null or session is null or refund_total is null or total_minor<>p.amount_minor or session is distinct from p.session_id or length(coalesce(intent,''))=0 or length(coalesce(charge,''))=0 or (p.payment_intent_id is not null and p.payment_intent_id<>intent) or (p.charge_id is not null and p.charge_id<>charge) or refund_total<0 or refund_total>total_minor then raise exception 'Provider evidence mismatch';end if;
 if exists(select 1 from public.payment_webhook_events where event_id=event_key) then return false;end if;
 if event_kind is null or event_kind not in ('paid','refund') then raise exception 'Unsupported event';end if;
 insert into public.payment_webhook_events values(event_key,event_kind,attempt,now());
 if event_kind in ('paid','refund') then
 if not exists(select 1 from public.verified_payments where provider='stripe' and provider_event_id='charge:'||charge) then
 insert into public.verified_payments(organization_id,booking_id,provider,provider_event_id,kind,amount_aed,currency,verified_at) values(p.organization_id,p.booking_id,'stripe','charge:'||charge,'charge',total_minor/100.0,'AED',now());
 perform private.passenger_notice(p.booking_id,'payment_confirmed','payment:'||charge);end if;
 delta=refund_total-p.refunded_minor;
 if delta>0 then insert into public.verified_payments(organization_id,booking_id,provider,provider_event_id,kind,amount_aed,currency,verified_at) values(p.organization_id,p.booking_id,'stripe',event_key,'refund',delta/100.0,'AED',now());end if;
 update public.payment_attempts set status=case when greatest(refund_total,p.refunded_minor)=p.amount_minor then 'refunded' else 'paid' end,payment_intent_id=intent,charge_id=charge,refunded_minor=greatest(refund_total,p.refunded_minor) where id=attempt;
 else if p.status not in ('paid','refunded') then update public.payment_attempts set status='failed' where id=attempt;perform private.passenger_notice(p.booking_id,'payment_failed','failed:'||attempt);end if;end if;
 return true;end;$function$

