CREATE OR REPLACE FUNCTION public.share_trip_location(trip_id uuid, lat double precision, lng double precision, accuracy_m double precision, captured timestamp with time zone, bearing double precision DEFAULT NULL::double precision, consent_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare driver uuid; trip public.bookings; previous public.trip_live_locations; begin
 driver=private.assigned_driver_id(); if driver is null then raise exception 'Driver access required' using errcode='42501'; end if;
 select * into trip from public.bookings where id=trip_id and driver_id=driver and not archived and status in ('confirmed','in_progress') for update;
 if not found or not private.live_trip_matches(trip_id,driver,trip.organization_id) then raise exception 'Active assignment required' using errcode='42501'; end if;
 if consent_id is null or not exists(select 1 from public.trip_location_consent where booking_id=trip_id and driver_id=driver and session_id=consent_id and expires_at>clock_timestamp()) then raise exception 'Sharing consent expired or revoked' using errcode='42501'; end if;
 if lat is null or lng is null or accuracy_m is null or captured is null or not(lat between -90 and 90 and lng between -180 and 180 and accuracy_m between 0 and 5000) or (bearing is not null and not(bearing>=0 and bearing<360)) then raise exception 'Invalid GPS data'; end if;
 if captured<clock_timestamp()-interval '30 seconds' or captured>clock_timestamp()+interval '5 seconds' then raise exception 'GPS timestamp is stale or in the future'; end if;
 select * into previous from public.trip_live_locations where booking_id=trip_id for update;
 if found and (captured<=previous.captured_at or clock_timestamp()-previous.received_at<interval '5 seconds') then raise exception 'GPS update is out of order or too frequent'; end if;
 insert into public.trip_live_locations(booking_id,organization_id,driver_id,latitude,longitude,accuracy,heading,captured_at,received_at)
 values(trip_id,trip.organization_id,driver,lat,lng,accuracy_m,bearing,captured,clock_timestamp())
 on conflict(booking_id) do update set driver_id=excluded.driver_id,latitude=excluded.latitude,longitude=excluded.longitude,accuracy=excluded.accuracy,heading=excluded.heading,captured_at=excluded.captured_at,received_at=excluded.received_at;
 update public.trip_location_consent set expires_at=clock_timestamp()+interval '2 minutes' where booking_id=trip_id and session_id=consent_id;
 perform private.notify_tracking(trip_id);
end; $function$

function:public.submit_booking_enquiry(b.definition:
CREATE OR REPLACE FUNCTION public.submit_booking_enquiry(business_id uuid, customer_name text, customer_email text, customer_phone text, pickup_id uuid, dropoff_id uuid, pickup_time timestamp with time zone, return_time timestamp with time zone, passenger_count integer, luggage_count integer, category text, transfer_kind text, flight text, customer_notes text, extra_ids uuid[], expected_total numeric)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q jsonb; ref text; notice_hours integer;
begin
 -- Service-role-only RPC. The Next.js action validates CAPTCHA before invoking this function.
 -- Serialize quotes/submissions and rate-limit server-verified enquiries per business/email.
 perform 1 from public.organizations where id=business_id for update;
 select minimum_notice_hours into notice_hours from public.business_settings where organization_id=business_id and published and enquiries_enabled for share;
 if not found then raise exception 'Online enquiries are unavailable'; end if;
 if customer_name is null or length(trim(customer_name)) not between 1 and 200 or customer_email is null or length(customer_email)>254 or customer_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' or customer_phone is null or length(trim(customer_phone)) not between 7 and 100 or passenger_count is null or passenger_count not between 1 and 1000 or luggage_count is null or luggage_count not between 0 and 1000 or length(flight)>200 or length(customer_notes)>4000 then raise exception 'Check your contact and passenger details'; end if;
 if pickup_time is null or pickup_time<now()+make_interval(hours=>notice_hours) or (transfer_kind='return' and (return_time is null or return_time<=pickup_time)) or (transfer_kind='one_way' and return_time is not null) then raise exception 'Check your pickup and return times'; end if;
 if (select count(*) from public.booking_enquiries where organization_id=business_id and created_at>now()-interval '1 hour')>=100 or (select count(*) from public.booking_enquiries where organization_id=business_id and email=lower(trim(customer_email)) and created_at>now()-interval '1 hour')>=3 then raise exception 'Please contact our team to continue your enquiry'; end if;
 -- Lock the price and extras to keep the quote snapshot consistent with the submitted records.
 perform 1 from public.route_pricing where organization_id=business_id and pickup_location_id=pickup_id and dropoff_location_id=dropoff_id and vehicle_category=category for share;
 perform 1 from public.pricing_extras where organization_id=business_id and id=any(extra_ids) order by id for share;
 q=public.calculate_transfer_quote(business_id,pickup_id,dropoff_id,category,transfer_kind,extra_ids);
 if expected_total is null or (q->>'total_aed')::numeric<>expected_total then raise exception 'Pricing changed. Please request a fresh quote'; end if;
 insert into public.booking_enquiries(organization_id,name,email,phone,pickup_location_id,dropoff_location_id,pickup_at,return_at,passengers,luggage,vehicle_category,transfer_type,flight_number,notes,extras,quoted_outbound_aed,quoted_return_aed,pricing_snapshot)
 values(business_id,trim(customer_name),lower(trim(customer_email)),trim(customer_phone),pickup_id,dropoff_id,pickup_time,return_time,passenger_count,luggage_count,category,transfer_kind,nullif(trim(flight),''),nullif(trim(customer_notes),''),extra_ids,(q->>'outbound_aed')::numeric,(q->>'return_aed')::numeric,q) returning reference into ref;
 return ref;
end; $function$
